-- EduSasa canonical 005: teacher/staff records used by the existing Teachers module.
CREATE TABLE IF NOT EXISTS teachers (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, employee_no VARCHAR(80) NOT NULL, first_name VARCHAR(100) NOT NULL, middle_name VARCHAR(100) NULL, last_name VARCHAR(100) NOT NULL, email VARCHAR(190) NULL, phone VARCHAR(40) NULL, gender VARCHAR(30) NULL, date_of_birth DATE NULL, department_id BIGINT UNSIGNED NULL, employment_type VARCHAR(60) NULL, status ENUM('active','inactive','suspended','left') NOT NULL DEFAULT 'active', joined_on DATE NULL, left_on DATE NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_teacher_school_employee(school_id,employee_no), KEY idx_teachers_school_department(school_id,department_id), KEY idx_teachers_school_status(school_id,status)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS teacher_subjects (school_id BIGINT UNSIGNED NOT NULL, teacher_id BIGINT UNSIGNED NOT NULL, subject_id BIGINT UNSIGNED NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY(teacher_id,subject_id), KEY idx_teacher_subject_school(school_id), KEY idx_teacher_subject_subject(subject_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS teacher_class_assignments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, school_id BIGINT UNSIGNED NOT NULL, teacher_id BIGINT UNSIGNED NOT NULL, class_id BIGINT UNSIGNED NOT NULL, stream_id BIGINT UNSIGNED NULL, role VARCHAR(80) NULL, starts_on DATE NULL, ends_on DATE NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, KEY idx_teacher_class_school(school_id,class_id), KEY idx_teacher_class_teacher(school_id,teacher_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
